function inside(root, candidate) {
  const relative = path.relative(root, candidate);
  return relative === "" || (!path.isAbsolute(relative) && relative !== ".." && !relative.startsWith(`..${path.sep}`));
}

async function readCandidate() {
  process.stdin.setEncoding("utf8");
  let candidate = "";
  for await (const chunk of process.stdin) candidate += chunk;
  return candidate;
}

async function absent(target) {
  try {
    await lstat(target);
    throw new Error(`Active report already exists: ${target}`);
  } catch (error) {
    if (error.code === "ENOENT") return;
    throw error;
  }
}

async function main() {
  const candidate = await readCandidate();
  const root = await realpath(rootArgument);
  const namespace = path.resolve(root, "docs/analysis/components/file");
  const target = path.resolve(targetArgument);
  const expected = path.resolve(namespace, "bin/csl-agent-kit.js.md");
  if (target !== expected || !inside(root, target) || !inside(namespace, target)) throw new Error("Unsafe active report path.");

  const rootStat = await lstat(root);
  if (rootStat.isSymbolicLink() || !rootStat.isDirectory()) throw new Error("Git root is not a canonical directory.");
  await absent(target);

  const parent = path.dirname(target);
  const relativeParent = path.relative(root, parent);
  if (path.isAbsolute(relativeParent) || relativeParent === ".." || relativeParent.startsWith(`..${path.sep}`)) throw new Error("Output parent escapes the Git root.");

  const records = [{ location: root, dev: rootStat.dev, ino: rootStat.ino }];
  let current = root;
  for (const segment of relativeParent.split(path.sep).filter(Boolean)) {
    current = path.join(current, segment);
    let stat;
    try {
      stat = await lstat(current);
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
      try { await mkdir(current); }
      catch (mkdirError) { if (mkdirError.code !== "EEXIST") throw mkdirError; }
      stat = await lstat(current);
    }
    if (stat.isSymbolicLink() || !stat.isDirectory()) throw new Error(`Unsafe output ancestor: ${current}`);
    if ((await realpath(current)) !== current) throw new Error(`Non-canonical output ancestor: ${current}`);
    records.push({ location: current, dev: stat.dev, ino: stat.ino });
  }

  async function recheckParents() {
    for (const record of records) {
      const stat = await lstat(record.location);
      if (stat.isSymbolicLink() || !stat.isDirectory() || stat.dev !== record.dev || stat.ino !== record.ino) throw new Error(`Output ancestor changed: ${record.location}`);
    }
  }

  await recheckParents();
  const temp = path.join(parent, `.${path.basename(target)}.${process.pid}.${randomUUID()}.tmp`);
  handle = await open(temp, "wx", 0o600);
  ownedTemp = temp;
  await handle.writeFile(candidate, "utf8");
  await handle.close();
  handle = null;

  await recheckParents();
  try { await link(temp, target); }
  catch (error) {
    if (error.code === "EEXIST") throw new Error(`Competing active report preserved: ${target}`);
    throw error;
  }
  await unlink(temp);
  ownedTemp = null;
  process.stdout.write(`${target}\n`);
}

