  process.stderr.write(`${error.message}\n`);
  process.exitCode = 1;
}).finally(async () => {
  if (handle) {
    try { await handle.close(); }
    catch (error) { process.stderr.write(`Temp close failed: ${error.message}\n`); process.exitCode = 1; }
  }
